const timezone = 'N8N_TIMEZONE';

// Google returns cancelled instances of recurring events too; they are not commitments.
const events = $input
  .all()
  .map((item) => item.json)
  .filter((event) => event && event.status !== 'cancelled' && (event.start?.dateTime || event.start?.date));

const isAllDay = (event) => !event.start?.dateTime && Boolean(event.start?.date);

function formatInZone(date, options) {
  try {
    return new Intl.DateTimeFormat('en-GB', { timeZone: timezone, ...options }).format(date);
  } catch (error) {
    return new Intl.DateTimeFormat('en-GB', { timeZone: 'UTC', ...options }).format(date);
  }
}

// en-CA gives YYYY-MM-DD, which sorts correctly as a plain string.
function dayKey(date) {
  const options = { year: 'numeric', month: '2-digit', day: '2-digit' };
  try {
    return new Intl.DateTimeFormat('en-CA', { timeZone: timezone, ...options }).format(date);
  } catch (error) {
    return new Intl.DateTimeFormat('en-CA', { timeZone: 'UTC', ...options }).format(date);
  }
}

// An all-day event carries a bare date; midday UTC keeps it on its own day in any zone.
const startDate = (event) => new Date(isAllDay(event) ? event.start.date + 'T12:00:00Z' : event.start.dateTime);

function bookedMinutes(event) {
  if (isAllDay(event)) return 0;
  const from = new Date(event.start.dateTime).getTime();
  const to = new Date(event.end?.dateTime ?? event.start.dateTime).getTime();
  return Math.max(0, Math.round((to - from) / 60000));
}

const byDay = new Map();
for (const event of events) {
  const key = dayKey(startDate(event));
  if (!byDay.has(key)) byDay.set(key, []);
  byDay.get(key).push(event);
}

const today = new Date();
const days = [];
for (let offset = 0; offset < 7; offset++) {
  days.push(dayKey(new Date(today.getTime() + offset * 86400000)));
}

const schedule = [];
let totalMinutes = 0;
let busiestDay = null;

for (const key of days) {
  const dayEvents = (byDay.get(key) ?? []).sort((a, b) => startDate(a) - startDate(b));
  const label = formatInZone(new Date(key + 'T12:00:00Z'), { weekday: 'short', day: 'numeric', month: 'short' });
  const dayMinutes = dayEvents.reduce((sum, event) => sum + bookedMinutes(event), 0);
  totalMinutes += dayMinutes;

  if (dayEvents.length) {
    const isBusier =
      !busiestDay ||
      dayMinutes > busiestDay.minutes ||
      (dayMinutes === busiestDay.minutes && dayEvents.length > busiestDay.count);
    if (isBusier) busiestDay = { label, minutes: dayMinutes, count: dayEvents.length };
  }

  schedule.push({
    label,
    entries: dayEvents.map((event) => ({
      when: isAllDay(event)
        ? 'all day'
        : formatInZone(new Date(event.start.dateTime), { hour: '2-digit', minute: '2-digit', hour12: false }) +
          (event.end?.dateTime
            ? '\u2013' + formatInZone(new Date(event.end.dateTime), { hour: '2-digit', minute: '2-digit', hour12: false })
            : ''),
      title: event.summary ?? '(no title)',
      place: event.location ?? '',
    })),
  });
}

const hours = Math.round((totalMinutes / 60) * 10) / 10;
const booked = hours > 0 ? ', ' + hours + 'h booked' : '';
const clearDays = schedule.filter((day) => day.entries.length === 0).length;

const subject = events.length === 0
  ? 'Week ahead \u2014 nothing scheduled'
  : 'Week ahead \u2014 ' + events.length + (events.length === 1 ? ' commitment' : ' commitments') + (hours > 0 ? ', ' + hours + 'h' : '');

const headline = events.length === 0
  ? 'Nothing on the calendar for the next seven days.'
  : events.length + (events.length === 1 ? ' commitment' : ' commitments') + ' over the next seven days' + booked + '.';

function escapeHtml(text) {
  const replacements = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  return String(text).replace(/[&<>"']/g, (character) => replacements[character]);
}

// Inline styles only: mail clients strip stylesheets.
const tableStyle = 'border-collapse:collapse;font:14px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif';
const headStyle = 'text-align:left;padding:6px 10px;border-bottom:2px solid #d0d0d0;font-weight:600';
const cellStyle = 'padding:6px 10px;border-bottom:1px solid #ececec;vertical-align:top';
const dayStyle = cellStyle + ';font-weight:600;white-space:nowrap';
const quietStyle = cellStyle + ';color:#999';

const htmlRows = schedule.map((day) => {
  if (day.entries.length === 0) {
    return '<tr><td style="' + dayStyle + ';color:#999">' + escapeHtml(day.label) + '</td>' +
           '<td style="' + quietStyle + '" colspan="2">\u2014</td></tr>';
  }
  return day.entries.map((entry, index) => {
    const place = entry.place ? '<div style="color:#777;font-size:12px">' + escapeHtml(entry.place) + '</div>' : '';
    return '<tr>' +
      '<td style="' + dayStyle + '">' + (index === 0 ? escapeHtml(day.label) : '') + '</td>' +
      '<td style="' + cellStyle + ';white-space:nowrap;color:#555">' + escapeHtml(entry.when) + '</td>' +
      '<td style="' + cellStyle + '">' + escapeHtml(entry.title) + place + '</td></tr>';
  }).join('');
}).join('');

const summaryBits = [
  busiestDay ? 'Busiest ' + busiestDay.label + ' (' + busiestDay.count + ')' : '',
  clearDays ? clearDays + ' clear ' + (clearDays === 1 ? 'day' : 'days') : '',
].filter((part) => part !== '').join(' \u00b7 ');

const html = '<div style="font:14px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#222">' +
  '<p style="margin:0 0 4px">' + escapeHtml(headline) + '</p>' +
  (summaryBits ? '<p style="margin:0 0 12px;color:#777;font-size:13px">' + escapeHtml(summaryBits) + '</p>' : '') +
  '<table style="' + tableStyle + '"><thead><tr>' +
  '<th style="' + headStyle + '">Day</th><th style="' + headStyle + '">When</th>' +
  '<th style="' + headStyle + '">Commitment</th></tr></thead><tbody>' + htmlRows + '</tbody></table></div>';

// Plain-text fallback, for clients that drop the HTML part.
const lines = [headline, summaryBits, ''];
for (const day of schedule) {
  if (day.entries.length === 0) {
    lines.push(day.label.padEnd(12) + ' \u2014');
    continue;
  }
  day.entries.forEach((entry, index) => {
    lines.push((index === 0 ? day.label.padEnd(12) : ''.padEnd(12)) + ' ' +
      entry.when.padEnd(12) + ' ' + entry.title + (entry.place ? ' (' + entry.place + ')' : ''));
  });
}
const content = lines.filter((line, index) => !(index === 1 && line === '')).join('\n');

return [{ json: { subject, content, html } }];
